import pandas as pd


def _get_input(inputs: dict, name: str):
    """Robustly fetch an input dataframe by name, tolerating case/formatting
    differences in the keys of the `inputs` dict."""
    if name in inputs:
        return inputs[name]
    lname = name.lower()
    for k, v in inputs.items():
        if isinstance(k, str) and k.lower() == lname:
            return v
    # fallback: try stripped/underscore-insensitive match
    norm = lname.replace("_", "")
    for k, v in inputs.items():
        if isinstance(k, str) and k.lower().replace("_", "") == norm:
            return v
    return None


def _differs(a, b):
    a_null = pd.isna(a)
    b_null = pd.isna(b)
    if a_null and b_null:
        return False
    if a_null != b_null:
        return True
    return a != b


def run(inputs: dict) -> dict:
    dim_product = _get_input(inputs, "DIM_PRODUCT")
    stg_product = _get_input(inputs, "STG_PRODUCT")

    if dim_product is None:
        dim_product = pd.DataFrame(
            columns=[
                "product_id",
                "category",
                "price_band",
                "eff_start_date",
                "eff_end_date",
                "is_current",
            ]
        )
    if stg_product is None:
        stg_product = pd.DataFrame(
            columns=["product_id", "category", "price_band", "update_date"]
        )

    # Ensure expected columns exist (defensive, in case of extra/renamed cols)
    for col in ["product_id", "category", "price_band", "eff_start_date",
                "eff_end_date", "is_current"]:
        if col not in dim_product.columns:
            dim_product[col] = pd.NA
    for col in ["product_id", "category", "price_band", "update_date"]:
        if col not in stg_product.columns:
            stg_product[col] = pd.NA

    # Build mutable list of output rows (as dicts) from existing dim table.
    output_rows = []
    current_map = {}

    for _, row in dim_product.iterrows():
        rec = {
            "product_id": row["product_id"],
            "category": row["category"],
            "price_band": row["price_band"],
            "eff_start_date": row["eff_start_date"],
            "eff_end_date": row["eff_end_date"],
            "is_current": row["is_current"],
        }
        output_rows.append(rec)
        if pd.notna(rec["is_current"]) and int(rec["is_current"]) == 1:
            current_map[rec["product_id"]] = rec

    # Sort staging data by product_id, update_date ascending (NOT deduplicated).
    if len(stg_product) > 0:
        stg_sorted = stg_product.sort_values(
            by=["product_id", "update_date"], kind="mergesort"
        )
    else:
        stg_sorted = stg_product

    for _, s in stg_sorted.iterrows():
        pid = s["product_id"]
        cat = s["category"]
        pb = s["price_band"]
        upd_date = s["update_date"]

        cur = current_map.get(pid)

        if cur is None:
            new_row = {
                "product_id": pid,
                "category": cat,
                "price_band": pb,
                "eff_start_date": upd_date,
                "eff_end_date": None,
                "is_current": 1,
            }
            output_rows.append(new_row)
            current_map[pid] = new_row
        else:
            changed = _differs(cur["category"], cat) or _differs(
                cur["price_band"], pb
            )
            if changed:
                cur["eff_end_date"] = upd_date
                cur["is_current"] = 0

                new_row = {
                    "product_id": pid,
                    "category": cat,
                    "price_band": pb,
                    "eff_start_date": upd_date,
                    "eff_end_date": None,
                    "is_current": 1,
                }
                output_rows.append(new_row)
                current_map[pid] = new_row
            # else no-op

    out_cols = [
        "product_id",
        "category",
        "price_band",
        "eff_start_date",
        "eff_end_date",
        "is_current",
    ]

    result = pd.DataFrame(output_rows, columns=out_cols)

    if not result.empty:
        # Determine product_id dtype preference
        pid_dtype = None
        if "product_id" in dim_product.columns and len(dim_product) > 0:
            pid_dtype = dim_product["product_id"].dtype
        elif "product_id" in stg_product.columns and len(stg_product) > 0:
            pid_dtype = stg_product["product_id"].dtype
        else:
            pid_dtype = "int64"

        try:
            result["product_id"] = result["product_id"].astype(pid_dtype)
        except (ValueError, TypeError):
            result["product_id"] = pd.to_numeric(
                result["product_id"], errors="coerce"
            ).astype("int64")

        result["eff_start_date"] = pd.to_datetime(
            result["eff_start_date"], errors="coerce"
        )
        result["eff_end_date"] = pd.to_datetime(
            result["eff_end_date"], errors="coerce"
        )
        result["is_current"] = result["is_current"].astype("int64")
    else:
        result = result.astype(
            {
                "product_id": "int64",
                "category": "object",
                "price_band": "object",
                "eff_start_date": "datetime64[ns]",
                "eff_end_date": "datetime64[ns]",
                "is_current": "int64",
            }
        )

    return {"dim_product_out": result}
